import{_ as a,o as n,c as i,ae as t}from"./chunks/framework.B2ul6ABY.js";const h=JSON.parse('{"title":"Goal Planning Runtime","description":"","frontmatter":{},"headers":[],"relativePath":"goal-planning-runtime.md","filePath":"goal-planning-runtime.md"}'),r={name:"goal-planning-runtime.md"};function o(l,e,s,c,d,p){return n(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="goal-planning-runtime" tabindex="-1">Goal Planning Runtime <a class="header-anchor" href="#goal-planning-runtime" aria-label="Permalink to &quot;Goal Planning Runtime&quot;">​</a></h1><p>This document describes the current accepted Saivage v3 planning model after the planner-control and evidence repair waves.</p><h2 id="core-model" tabindex="-1">Core model <a class="header-anchor" href="#core-model" aria-label="Permalink to &quot;Core model&quot;">​</a></h2><p>Saivage coordinates work through three runtime roles:</p><ul><li><strong>Planner</strong> — decomposes goal work and decides whether the goal should continue, block, or move toward review.</li><li><strong>Executor</strong> — performs concrete terminal work.</li><li><strong>Reviewer</strong> — validates a goal against its acceptance criteria before goal completion.</li></ul><p>The key current rule is:</p><ul><li><strong>planning state is owned by goals</strong>;</li><li><strong>operators should not model planning as separate visible plan cards</strong>.</li></ul><h2 id="durable-control-state" tabindex="-1">Durable control state <a class="header-anchor" href="#durable-control-state" aria-label="Permalink to &quot;Durable control state&quot;">​</a></h2><p>Current runtime behavior persists control state under <code>.saivage/runtime/</code>, including planner-control frames and dispatch records. This allows parent planners to suspend while child work runs and then resume with durable evidence.</p><p>Current accepted semantics include:</p><ul><li>parent planners can suspend around child dispatches;</li><li>child completion can make a parent planner resumable;</li><li>dispatch completion is expected to preserve evidence rather than silently disappearing into queue churn.</li></ul><h2 id="goal-level-contract" tabindex="-1">Goal-level contract <a class="header-anchor" href="#goal-level-contract" aria-label="Permalink to &quot;Goal-level contract&quot;">​</a></h2><p>A goal is not complete merely because it has no ready child work at a moment in time. Instead:</p><ol><li>the planner inspects current goal state;</li><li>the planner creates or updates child work;</li><li>child goal or terminal-card work is dispatched;</li><li>completion evidence is gathered;</li><li>the parent planner resumes if further planning is needed;</li><li>review gates final goal completion.</li></ol><p>This means an empty ready queue is only an execution snapshot, not a completion proof.</p><h2 id="planner-outcomes" tabindex="-1">Planner outcomes <a class="header-anchor" href="#planner-outcomes" aria-label="Permalink to &quot;Planner outcomes&quot;">​</a></h2><p>Current planner behavior still uses the familiar <code>continue | done | blocked</code> outcome pattern, but runtime semantics are stricter than the string alone.</p><h3 id="continue" tabindex="-1"><code>continue</code> <a class="header-anchor" href="#continue" aria-label="Permalink to &quot;`continue`&quot;">​</a></h3><p>The planner believes more work is required.</p><h3 id="blocked" tabindex="-1"><code>blocked</code> <a class="header-anchor" href="#blocked" aria-label="Permalink to &quot;`blocked`&quot;">​</a></h3><p>The planner or child work has identified a blocking condition that must be surfaced.</p><h3 id="done" tabindex="-1"><code>done</code> <a class="header-anchor" href="#done" aria-label="Permalink to &quot;`done`&quot;">​</a></h3><p><code>done</code> is meaningful only when acceptance and review conditions are actually satisfied. It must not be treated as valid proof if child work still requires execution or evidence is missing.</p><h2 id="review-gate" tabindex="-1">Review gate <a class="header-anchor" href="#review-gate" aria-label="Permalink to &quot;Review gate&quot;">​</a></h2><p>Reviewer behavior remains part of the completion contract:</p><ul><li>a goal should not be treated as complete solely because planning stopped creating more children;</li><li>review is the final acceptance gate for goal completion;</li><li>failed review can send the goal back into further planning.</li></ul><h2 id="evidence-expectations" tabindex="-1">Evidence expectations <a class="header-anchor" href="#evidence-expectations" aria-label="Permalink to &quot;Evidence expectations&quot;">​</a></h2><p>Current accepted behavior requires durable evidence around child execution and goal review. Relevant evidence may include:</p><ul><li>generated files</li><li>verification commands</li><li>tool errors</li><li>attachments and artifacts</li><li>parse-failure context when an executor response is malformed after useful work already occurred</li></ul><p>Operators inspect this evidence primarily through card detail rather than by reading raw runtime files.</p><h2 id="relationship-to-project-level-planning" tabindex="-1">Relationship to project-level planning <a class="header-anchor" href="#relationship-to-project-level-planning" aria-label="Permalink to &quot;Relationship to project-level planning&quot;">​</a></h2><p>Project-level planning remains strategic, but goal-level planning is the main current durable owner for planning state. The runtime should preserve parent control across child work rather than relying on incidental queue exhaustion.</p><h2 id="operator-implications" tabindex="-1">Operator implications <a class="header-anchor" href="#operator-implications" aria-label="Permalink to &quot;Operator implications&quot;">​</a></h2><p>Operators should use this model when interpreting runtime state:</p><ul><li>do not infer completion from empty queues alone;</li><li>inspect card detail evidence for generated work;</li><li>inspect agent and debug views when a planner appears stuck or when evidence is incomplete;</li><li>treat blocked, degraded, and frozen states as explicit runtime signals.</li></ul><h2 id="source-grounding" tabindex="-1">Source grounding <a class="header-anchor" href="#source-grounding" aria-label="Permalink to &quot;Source grounding&quot;">​</a></h2><p>This page reflects the repaired system shape established across stages 07-10, especially:</p><ul><li>planner-control durability and derived-state/card validation;</li><li>evidence preservation and malformed-result handling improvements;</li><li>generated-file inspection and safe preview behavior;</li><li>operator-facing UI workflows for current state inspection.</li></ul>',38)])])}const m=a(r,[["render",o]]);export{h as __pageData,m as default};
